Method.Implementation:
#dim tSC As %Status=$$$OK #dim pRequest As IHC.ITF.Oax.Dstruc.OaxDelimited.Record $$$TRACE("Processing Record with ID "_pInput.Get("MSPR_DEMOGRAPHICS_ID")) // Read one record at a time and send the request to the Target config name do{ try{ set pRequest= ##class(IHC.ITF.Oax.Dstruc.OaxDelimited.Record).%New() set pRequest.MSPRDEMOGRAPHICSID = pInput.Get("MSPR_DEMOGRAPHICS_ID") set pRequest.PERSONID = pInput.Get("PERSON_ID") set pRequest.USERTYPE = pInput.Get("USER_TYPE") set pRequest.STARTDATE = pInput.Get("START_DATE") set pRequest.ENDDATE = pInput.Get("END_DATE") set pRequest.SSN = pInput.Get("SSN") set pRequest.LASTNAME = pInput.Get("LAST_NAME") set pRequest.FIRSTNAME = pInput.Get("FIRST_NAME") set pRequest.MIDDLENAME = pInput.Get("MIDDLE_NAMES") set pRequest.DATEOFBIRTH = pInput.Get("DATE_OF_BIRTH") set pRequest.EMAILADDRESS = pInput.Get("EMAIL_ADDRESS") set pRequest.FACILITYNUMBER = pInput.Get("FACILITY_NUMBER") set pRequest.SUPERVISORMSPRID = pInput.Get("SUPERVISOR_MSPR_ID") set pRequest.MSPRPROCESSEDDATE = " " set pRequest.CREATIONDATE = pInput.Get("CREATION_DATE") set pRequest.CREATEDBY = pInput.Get("CREATED_BY") set pRequest.LASTUPDATEDDATE = pInput.Get("LAST_UPDATE_DATE") set pRequest.LASTUPDATEDBY = pInput.Get("LAST_UPDATED_BY") set pRequest.GENDER = pInput.Get("GENDER") set pRequest.PREFERREDNAME = pInput.Get("PREFERRED_NAME") set pRequest.NONUSID = pInput.Get("NON_US_NATIONAL_IDENTIFIER") set pRequest.PREVIOUSNAME = pInput.Get("PREVIOUS_NAME") set pRequest.ACCESSSTATUS = pInput.Get("ACCESS_STATUS") set pRequest.INTERMOUNTAINEMP = pInput.Get("INTERMOUNTAIN_EMP") set pRequest.USERNAME = pInput.Get("USER_NAME") set pRequest.EMPLOYEENUMBER = pInput.Get("EMPLOYEE_NUMBER") set pRequest.NAMESUFFIX = pInput.Get("NAME_SUFFIX") set pRequest.SCHOOLNUMBER = " " set pRequest.ROTATIONNUMBER = " " do ..SendRequestAsync(..TargetConfigNames,pRequest) }catch e{ set tSC=##class(IHC.ITF.ITFCOMMON.Utility).FailMsgError(..%ConfigName, e.code_" "_e.Data) }
}while(0)
quit tSC

Do ##super(.pArray,pItem)
If pItem.GetModifiedSetting("TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") { Set tOne=$ZStrip($P(tValue,",",i),"<>W")  Continue:""=tOne  Set pArray(tOne)="" }
}
